        private static void AddWelcomeStrings()
        {
            Add("Добро пожаловать в CyrFlip", en: "Welcome to CyrFlip", uk: "Вітаємо в CyrFlip", de: "Willkommen bei CyrFlip", it: "Benvenuto in CyrFlip", es: "Bienvenido a CyrFlip", fr: "Bienvenue dans CyrFlip", pt: "Bem-vindo ao CyrFlip", ar: "مرحبًا بك في CyrFlip", hi: "CyrFlip में स्वागत है", bn: "CyrFlip-এ স্বাগতম", ur: "CyrFlip میں خوش آمدید", zh: "欢迎使用 CyrFlip");
            Add("Показать приветствие..", en: "Show the welcome tour..", uk: "Показати привітання..", de: "Einführung anzeigen..", it: "Mostra la guida iniziale..", es: "Mostrar la bienvenida..", fr: "Afficher la visite de bienvenue..", pt: "Mostrar a apresentação..", ar: "عرض جولة الترحيب..", hi: "स्वागत परिचय दिखाएँ..", bn: "স্বাগত পরিচিতি দেখান..", ur: "تعارفی دورہ دکھائیں..", zh: "显示欢迎导览..");
            Add("Знакомство с CyrFlip и первоначальная настройка.", en: "Get to know CyrFlip and set it up.", uk: "Знайомство з CyrFlip і початкове налаштування.", de: "CyrFlip kennenlernen und einrichten.", it: "Scopri CyrFlip e configuralo.", es: "Conoce CyrFlip y configúralo.", fr: "Découvrez CyrFlip et configurez-le.", pt: "Conheça o CyrFlip e configure-o.", ar: "تعرّف على CyrFlip وأعدّه.", hi: "CyrFlip को जानें और सेट अप करें।", bn: "CyrFlip সম্পর্কে জানুন ও সেট আপ করুন।", ur: "CyrFlip کو جانیں اور ترتیب دیں۔", zh: "了解并设置 CyrFlip。");
            Add("CyrFlip исправляет текст в неверной раскладке, показывает активный язык и живёт в трее. Всё можно изменить позже.", en: "CyrFlip fixes text typed in the wrong layout, shows the active language and lives in the tray. Everything can be changed later.", uk: "CyrFlip виправляє текст у хибній розкладці, показує активну мову та працює в треї. Усе можна змінити пізніше.", de: "CyrFlip korrigiert Text im falschen Tastaturlayout, zeigt die aktive Sprache und läuft im Infobereich. Alles lässt sich später ändern.", it: "CyrFlip corregge il testo digitato con il layout errato, mostra la lingua attiva e resta nell’area di notifica. Tutto si può cambiare in seguito.", es: "CyrFlip corrige texto escrito con la distribución incorrecta, muestra el idioma activo y vive en la bandeja. Todo se puede cambiar después.", fr: "CyrFlip corrige le texte saisi avec la mauvaise disposition, indique la langue active et reste dans la zone de notification. Tout peut être modifié plus tard.", pt: "O CyrFlip corrige texto digitado no layout errado, mostra o idioma ativo e fica na bandeja. Tudo pode ser alterado depois.", ar: "يصحح CyrFlip النص المكتوب بتخطيط خاطئ ويعرض اللغة النشطة ويعمل في علبة النظام. يمكن تغيير كل شيء لاحقًا.", hi: "CyrFlip गलत लेआउट में टाइप किए पाठ को सुधारता है, सक्रिय भाषा दिखाता है और ट्रे में रहता है। सब कुछ बाद में बदल सकते हैं।", bn: "CyrFlip ভুল লেআউটে লেখা ঠিক করে, সক্রিয় ভাষা দেখায় এবং ট্রেতে থাকে। সবকিছু পরে বদলানো যায়।", ur: "CyrFlip غلط لے آؤٹ میں لکھا متن درست کرتا ہے، فعال زبان دکھاتا ہے اور ٹرے میں رہتا ہے۔ سب کچھ بعد میں بدلا جا سکتا ہے۔", zh: "CyrFlip 修正使用错误布局输入的文本，显示当前语言，并驻留在托盘中。所有选项都可稍后更改。");
            Add("Метка у каретки: {0}. Курсор мыши: {1} (меняется во всей системе). Значок в трее показывает раскладку.", en: "Caret marker: {0}. Mouse cursor: {1} (a system-wide change). The tray icon shows the layout.", uk: "Позначка біля каретки: {0}. Курсор миші: {1} (змінюється в усій системі). Значок у треї показує розкладку.", de: "Markierung am Textcursor: {0}. Mauszeiger: {1} (systemweite Änderung). Das Symbol im Infobereich zeigt das Layout.", it: "Indicatore al cursore di testo: {0}. Cursore del mouse: {1} (modifica di sistema). L’icona nell’area di notifica mostra il layout.", es: "Marca junto al cursor de texto: {0}. Cursor del ratón: {1} (cambio en todo el sistema). El icono de la bandeja muestra la distribución.", fr: "Repère au curseur de texte : {0}. Curseur de souris : {1} (changement dans tout le système). L’icône indique la disposition.", pt: "Marcador no cursor de texto: {0}. Cursor do mouse: {1} (alteração em todo o sistema). O ícone da bandeja mostra o layout.", ar: "علامة مؤشر النص: {0}. مؤشر الفأرة: {1} (تغيير على مستوى النظام). تعرض أيقونة العلبة التخطيط.", hi: "टेक्स्ट कर्सर चिह्न: {0}। माउस कर्सर: {1} (पूरे सिस्टम में बदलाव)। ट्रे आइकन लेआउट दिखाता है।", bn: "টেক্সট কার্সারের চিহ্ন: {0}। মাউস কার্সার: {1} (পুরো সিস্টেমে পরিবর্তন)। ট্রে আইকন লেআউট দেখায়।", ur: "متن کرسر کا نشان: {0}۔ ماؤس کرسر: {1} (پورے نظام میں تبدیلی)۔ ٹرے کا آئیکن لے آؤٹ دکھاتا ہے۔", zh: "插入点标记：{0}。鼠标光标：{1}（系统范围的更改）。托盘图标显示布局。");
            Add("Переключите раскладку в своём редакторе и посмотрите на метку.", en: "Switch the layout in your editor and watch the marker.", uk: "Перемкніть розкладку у своєму редакторі та подивіться на позначку.", de: "Wechseln Sie das Layout in Ihrem Editor und beobachten Sie die Markierung.", it: "Cambia layout nel tuo editor e osserva l’indicatore.", es: "Cambia la distribución en tu editor y observa la marca.", fr: "Changez de disposition dans votre éditeur et observez le repère.", pt: "Mude o layout no seu editor e observe o marcador.", ar: "بدّل التخطيط في محررك وراقب العلامة.", hi: "अपने संपादक में लेआउट बदलें और चिह्न देखें।", bn: "নিজের সম্পাদকে লেআউট বদলান এবং চিহ্ন দেখুন।", ur: "اپنے ایڈیٹر میں لے آؤٹ بدلیں اور نشان دیکھیں۔", zh: "在您的编辑器中切换布局并观察标记。");
            Add("Пример: выделите {0}, затем нажмите комбинацию выше.", en: "Example: select {0}, then press the shortcut above.", uk: "Приклад: виділіть {0}, потім натисніть комбінацію вище.", de: "Beispiel: Markieren Sie {0} und drücken Sie die obige Tastenkombination.", it: "Esempio: seleziona {0}, poi premi la combinazione sopra.", es: "Ejemplo: selecciona {0} y pulsa el atajo indicado arriba.", fr: "Exemple : sélectionnez {0}, puis appuyez sur le raccourci ci-dessus.", pt: "Exemplo: selecione {0} e pressione o atalho acima.", ar: "مثال: حدد {0} ثم اضغط الاختصار أعلاه.", hi: "उदाहरण: {0} चुनें, फिर ऊपर दिया शॉर्टकट दबाएँ।", bn: "উদাহরণ: {0} নির্বাচন করুন, তারপর উপরের শর্টকাট চাপুন।", ur: "مثال: {0} منتخب کریں، پھر اوپر دیا شارٹ کٹ دبائیں۔", zh: "示例：选中 {0}，然后按上述快捷键。");
            Add("Таблица конвертации пуста. Добавьте пару в настройках.", en: "The conversion table is empty. Add a pair in settings.", uk: "Таблиця конвертації порожня. Додайте пару в налаштуваннях.", de: "Die Konvertierungstabelle ist leer. Fügen Sie in den Einstellungen ein Paar hinzu.", it: "La tabella di conversione è vuota. Aggiungi una coppia nelle impostazioni.", es: "La tabla de conversión está vacía. Añade un par en ajustes.", fr: "La table de conversion est vide. Ajoutez une paire dans les paramètres.", pt: "A tabela de conversão está vazia. Adicione um par nas configurações.", ar: "جدول التحويل فارغ. أضف زوجًا في الإعدادات.", hi: "रूपांतरण तालिका खाली है। सेटिंग में एक जोड़ी जोड़ें।", bn: "রূপান্তর সারণি খালি। সেটিংসে একটি জোড়া যোগ করুন।", ur: "تبدیلی کی جدول خالی ہے۔ ترتیبات میں ایک جوڑا شامل کریں۔", zh: "转换表为空。请在设置中添加一对布局。");
            Add("{0} ⇄ {1}: {2} ({3}). Выделите текст и нажмите комбинацию.", en: "{0} ⇄ {1}: {2} ({3}). Select text and press the shortcut.", uk: "{0} ⇄ {1}: {2} ({3}). Виділіть текст і натисніть комбінацію.", de: "{0} ⇄ {1}: {2} ({3}). Text markieren und Tastenkombination drücken.", it: "{0} ⇄ {1}: {2} ({3}). Seleziona il testo e premi la combinazione.", es: "{0} ⇄ {1}: {2} ({3}). Selecciona texto y pulsa el atajo.", fr: "{0} ⇄ {1} : {2} ({3}). Sélectionnez le texte et appuyez sur le raccourci.", pt: "{0} ⇄ {1}: {2} ({3}). Selecione o texto e pressione o atalho.", ar: "{0} ⇄ {1}: {2} ({3}). حدد النص واضغط الاختصار.", hi: "{0} ⇄ {1}: {2} ({3})। पाठ चुनें और शॉर्टकट दबाएँ।", bn: "{0} ⇄ {1}: {2} ({3})। লেখা নির্বাচন করে শর্টকাট চাপুন।", ur: "{0} ⇄ {1}: {2} ({3})۔ متن منتخب کریں اور شارٹ کٹ دبائیں۔", zh: "{0} ⇄ {1}：{2}（{3}）。选中文本并按快捷键。");
            Add("Смена регистра: {0} ({1}) — если оставили CapsLock включённым.", en: "Change case: {0} ({1}) — if you left CapsLock on.", uk: "Зміна регістру: {0} ({1}) — якщо залишили CapsLock увімкненим.", de: "Groß-/Kleinschreibung: {0} ({1}) — wenn CapsLock noch eingeschaltet war.", it: "Cambia maiuscole/minuscole: {0} ({1}) — se hai lasciato CapsLock attivo.", es: "Cambiar mayúsculas: {0} ({1}) — si dejaste CapsLock activado.", fr: "Changer la casse : {0} ({1}) — si CapsLock était resté actif.", pt: "Alterar maiúsculas: {0} ({1}) — se deixou CapsLock ligado.", ar: "تغيير حالة الأحرف: {0} ({1}) — إذا تركت CapsLock مفعّلًا.", hi: "अक्षर केस बदलें: {0} ({1}) — यदि CapsLock चालू रह गया हो।", bn: "অক্ষরের কেস বদলান: {0} ({1}) — CapsLock চালু রেখে দিলে।", ur: "حروف کی حالت بدلیں: {0} ({1}) — اگر CapsLock فعال رہ گیا ہو۔", zh: "切换大小写：{0}（{1}）— 适用于忘记关闭 CapsLock 的情况。");
            Add("CyrFlip копирует, преобразует и вставляет текст, затем возвращает буфер обмена.", en: "CyrFlip copies, converts and pastes text, then restores the clipboard.", uk: "CyrFlip копіює, перетворює та вставляє текст, потім відновлює буфер обміну.", de: "CyrFlip kopiert, konvertiert und fügt Text ein und stellt danach die Zwischenablage wieder her.", it: "CyrFlip copia, converte e incolla il testo, poi ripristina gli appunti.", es: "CyrFlip copia, convierte y pega texto, y luego restaura el portapapeles.", fr: "CyrFlip copie, convertit et colle le texte, puis restaure le presse-papiers.", pt: "O CyrFlip copia, converte e cola o texto, depois restaura a área de transferência.", ar: "ينسخ CyrFlip النص ويحوّله ويلصقه، ثم يعيد الحافظة.", hi: "CyrFlip पाठ कॉपी, रूपांतरित और पेस्ट करता है, फिर क्लिपबोर्ड बहाल करता है।", bn: "CyrFlip লেখা কপি, রূপান্তর ও পেস্ট করে, তারপর ক্লিপবোর্ড ফিরিয়ে দেয়।", ur: "CyrFlip متن کاپی، تبدیل اور پیسٹ کرتا ہے، پھر کلپ بورڈ بحال کرتا ہے۔", zh: "CyrFlip 复制、转换并粘贴文本，然后还原剪贴板。");
            Add("Дополнительные возможности", en: "Optional features", uk: "Додаткові можливості", de: "Optionale Funktionen", it: "Funzioni facoltative", es: "Funciones opcionales", fr: "Fonctions facultatives", pt: "Recursos opcionais", ar: "ميزات اختيارية", hi: "वैकल्पिक सुविधाएँ", bn: "ঐচ্ছিক সুবিধা", ur: "اختیاری سہولتیں", zh: "可选功能");
            Add("Снимок области экрана: {0} ({1}). Остальные модули включаются в настройках.", en: "Screen-region capture: {0} ({1}). Other modules can be enabled in settings.", uk: "Знімок області екрана: {0} ({1}). Решта модулів вмикаються в налаштуваннях.", de: "Bildschirmausschnitt: {0} ({1}). Weitere Module lassen sich in den Einstellungen einschalten.", it: "Cattura area dello schermo: {0} ({1}). Gli altri moduli si attivano nelle impostazioni.", es: "Captura de región: {0} ({1}). Los demás módulos se activan en ajustes.", fr: "Capture d’une zone : {0} ({1}). Les autres modules s’activent dans les paramètres.", pt: "Captura de região: {0} ({1}). Os outros módulos podem ser ativados nas configurações.", ar: "التقاط منطقة الشاشة: {0} ({1}). يمكن تفعيل الوحدات الأخرى في الإعدادات.", hi: "स्क्रीन क्षेत्र कैप्चर: {0} ({1})। अन्य मॉड्यूल सेटिंग में चालू कर सकते हैं।", bn: "স্ক্রিন অঞ্চল ধারণ: {0} ({1})। অন্য মডিউল সেটিংসে চালু করা যায়।", ur: "اسکرین حصے کی تصویر: {0} ({1})۔ دیگر ماڈیول ترتیبات میں فعال کیے جا سکتے ہیں۔", zh: "屏幕区域截图：{0}（{1}）。其他模块可在设置中启用。");
            Add("Установка и предупреждение SmartScreen", en: "Installation and the SmartScreen warning", uk: "Встановлення та попередження SmartScreen", de: "Installation und SmartScreen-Warnung", it: "Installazione e avviso SmartScreen", es: "Instalación y aviso de SmartScreen", fr: "Installation et avertissement SmartScreen", pt: "Instalação e aviso do SmartScreen", ar: "التثبيت وتحذير SmartScreen", hi: "स्थापना और SmartScreen चेतावनी", bn: "ইনস্টলেশন ও SmartScreen সতর্কতা", ur: "تنصیب اور SmartScreen انتباہ", zh: "安装与 SmartScreen 警告");
            Add("Где находится CyrFlip", en: "Where CyrFlip lives", uk: "Де знаходиться CyrFlip", de: "Wo CyrFlip zu finden ist", it: "Dove si trova CyrFlip", es: "Dónde está CyrFlip", fr: "Où trouver CyrFlip", pt: "Onde encontrar o CyrFlip", ar: "أين تجد CyrFlip", hi: "CyrFlip कहाँ रहता है", bn: "CyrFlip কোথায় থাকে", ur: "CyrFlip کہاں ملتا ہے", zh: "在哪里找到 CyrFlip");
            Add("Значок в трее: щелчок переключает язык, двойной щелчок открывает настройки, правый щелчок открывает меню.", en: "Tray icon: click to switch language, double-click for settings, right-click for the menu.", uk: "Значок у треї: клацання перемикає мову, подвійне відкриває налаштування, праве відкриває меню.", de: "Symbol im Infobereich: Klick wechselt die Sprache, Doppelklick öffnet Einstellungen, Rechtsklick das Menü.", it: "Icona nell’area di notifica: clic per cambiare lingua, doppio clic per le impostazioni, clic destro per il menu.", es: "Icono de bandeja: clic para cambiar idioma, doble clic para ajustes, clic derecho para el menú.", fr: "Icône de notification : clic pour changer de langue, double-clic pour les paramètres, clic droit pour le menu.", pt: "Ícone da bandeja: clique para mudar o idioma, clique duplo para configurações, clique direito para o menu.", ar: "أيقونة العلبة: نقرة تبدّل اللغة، نقرتان تفتحان الإعدادات، والنقرة اليمنى تفتح القائمة.", hi: "ट्रे आइकन: क्लिक से भाषा बदलें, डबल-क्लिक से सेटिंग खोलें, दाएँ क्लिक से मेनू खोलें।", bn: "ট্রে আইকন: ক্লিকে ভাষা বদলায়, ডাবল-ক্লিকে সেটিংস খোলে, ডান ক্লিকে মেনু খোলে।", ur: "ٹرے آئیکن: کلک زبان بدلتا ہے، ڈبل کلک ترتیبات کھولتا ہے، دایاں کلک مینو کھولتا ہے۔", zh: "托盘图标：单击切换语言，双击打开设置，右键打开菜单。");
            Add("Windows 11 может скрыть новый значок за стрелкой ^. Перетащите его наружу, чтобы видеть постоянно.", en: "Windows 11 may hide a new icon behind the ^ arrow. Drag it out to keep it visible.", uk: "Windows 11 може сховати новий значок за стрілкою ^. Перетягніть його назовні, щоб бачити постійно.", de: "Windows 11 kann ein neues Symbol hinter dem Pfeil ^ verbergen. Ziehen Sie es heraus, damit es sichtbar bleibt.", it: "Windows 11 può nascondere una nuova icona dietro la freccia ^. Trascinala fuori per tenerla visibile.", es: "Windows 11 puede ocultar un icono nuevo tras la flecha ^. Arrástralo fuera para mantenerlo visible.", fr: "Windows 11 peut masquer une nouvelle icône derrière la flèche ^. Faites-la glisser dehors pour la garder visible.", pt: "O Windows 11 pode ocultar um ícone novo atrás da seta ^. Arraste-o para fora para mantê-lo visível.", ar: "قد يخفي Windows 11 الأيقونة الجديدة خلف السهم ^. اسحبها للخارج لتبقى ظاهرة.", hi: "Windows 11 नया आइकन ^ तीर के पीछे छिपा सकता है। उसे बाहर खींचकर हमेशा दिखाएँ।", bn: "Windows 11 নতুন আইকন ^ তীরের পেছনে লুকাতে পারে। বাইরে টেনে এনে দৃশ্যমান রাখুন।", ur: "Windows 11 نیا آئیکن ^ تیر کے پیچھے چھپا سکتا ہے۔ اسے باہر کھینچیں تاکہ نظر آتا رہے۔", zh: "Windows 11 可能将新图标隐藏在 ^ 箭头后。将其拖出即可保持可见。");
            Add("Ярлыки CyrFlip доступны в меню «Пуск» или на рабочем столе.", en: "CyrFlip shortcuts are available in Start or on the desktop.", uk: "Ярлики CyrFlip доступні в меню «Пуск» або на робочому столі.", de: "CyrFlip-Verknüpfungen sind im Startmenü oder auf dem Desktop verfügbar.", it: "I collegamenti a CyrFlip sono disponibili in Start o sul desktop.", es: "Los accesos directos de CyrFlip están en Inicio o en el escritorio.", fr: "Les raccourcis CyrFlip sont disponibles dans Démarrer ou sur le bureau.", pt: "Os atalhos do CyrFlip estão no menu Iniciar ou na área de trabalho.", ar: "اختصارات CyrFlip متاحة في قائمة ابدأ أو على سطح المكتب.", hi: "CyrFlip शॉर्टकट स्टार्ट या डेस्कटॉप पर उपलब्ध हैं।", bn: "CyrFlip শর্টকাট স্টার্ট বা ডেস্কটপে পাওয়া যায়।", ur: "CyrFlip کے شارٹ کٹ اسٹارٹ یا ڈیسک ٹاپ پر دستیاب ہیں۔", zh: "CyrFlip 快捷方式位于开始菜单或桌面。");
            Add("Сначала распакуйте CyrFlip в постоянную папку: временная папка исчезнет, и автозапуск с ярлыками перестанут работать.", en: "Unpack CyrFlip to a permanent folder first: a temporary folder will disappear, breaking startup and shortcuts.", uk: "Спочатку розпакуйте CyrFlip у постійну папку: тимчасова зникне, і автозапуск з ярликами перестануть працювати.", de: "Entpacken Sie CyrFlip zuerst in einen dauerhaften Ordner: Ein temporärer Ordner verschwindet, Autostart und Verknüpfungen funktionieren dann nicht mehr.", it: "Estrai prima CyrFlip in una cartella permanente: quella temporanea sparirà e avvio automatico e collegamenti non funzioneranno più.", es: "Extrae primero CyrFlip a una carpeta permanente: la temporal desaparecerá y el inicio automático y los accesos dejarán de funcionar.", fr: "Décompressez d’abord CyrFlip dans un dossier permanent : le dossier temporaire disparaîtra, empêchant le démarrage et les raccourcis de fonctionner.", pt: "Extraia primeiro o CyrFlip para uma pasta permanente: a temporária desaparecerá, interrompendo a inicialização e os atalhos.", ar: "فك ضغط CyrFlip في مجلد دائم أولًا: سيختفي المجلد المؤقت ويتوقف التشغيل التلقائي والاختصارات.", hi: "पहले CyrFlip स्थायी फ़ोल्डर में निकालें: अस्थायी फ़ोल्डर मिट जाएगा और स्टार्टअप व शॉर्टकट काम नहीं करेंगे।", bn: "আগে CyrFlip স্থায়ী ফোল্ডারে আনপ্যাক করুন: অস্থায়ী ফোল্ডার মুছে গেলে স্টার্টআপ ও শর্টকাট কাজ করবে না।", ur: "پہلے CyrFlip مستقل فولڈر میں نکالیں: عارضی فولڈر مٹ جائے گا اور خودکار آغاز اور شارٹ کٹ کام نہیں کریں گے۔", zh: "请先将 CyrFlip 解压到永久文件夹：临时文件夹会消失，导致自动启动和快捷方式失效。");
            Add("Включено", en: "On", uk: "Увімкнено", de: "Ein", it: "Attivo", es: "Activado", fr: "Activé", pt: "Ativado", ar: "مفعّل", hi: "चालू", bn: "চালু", ur: "فعال", zh: "已启用");
